import type { Metadata } from "next";

import { PremiumQuoteClient } from "./premium-quote-client";

export const metadata: Metadata = {
    title: "医療保険の保険料をためす（試算）",
    description:
        "年齢・入院日額・保障の期間・特約を動かしながら、毎月の保険料と払込の総額の目安を確かめられる試算画面です。金額はすべて目安で、実際の保険料は告知と審査によって決まります。",
};

export default function PremiumQuotePage() {
    return <PremiumQuoteClient />;
}

/**
 * 医療保険 保険料シミュレーション（目安）のモデル。
 *
 * ここで出す金額はすべて「目安」です。実在の商品・料率とは無関係の、
 * デモ用の簡易モデルで、実際の保険料は年齢・性別・健康状態の告知内容や
 * 保険会社の審査によって変わります。
 */

export type Sex = "male" | "female";
/** 保障の期間 */
export type CoverageTerm = "y10" | "y20" | "whole";
/** 払込の期間 */
export type PaymentTerm = "full" | "whole" | "to60" | "to65";
export type RiderId = "advanced" | "cancer" | "outpatient" | "women";

export interface QuoteInput {
    /** 年齢（満年齢） */
    age: number;
    sex: Sex;
    /** 入院日額（円） */
    dailyAmount: number;
    coverageTerm: CoverageTerm;
    paymentTerm: PaymentTerm;
    /** 手術給付の倍率（入院日額の何倍か） */
    surgeryMultiplier: number;
    riders: RiderId[];
}

export const AGE_MIN = 18;
export const AGE_MAX = 75;
export const DAILY_MIN = 5_000;
export const DAILY_MAX = 20_000;
export const DAILY_STEP = 1_000;
export const SURGERY_MULTIPLIERS = [10, 20, 40] as const;

/** 終身払のとき、払込がいつまで続くと見込むか（払込総額の目安を出すための仮置き） */
export const WHOLE_PAY_ASSUMED_END_AGE = 88;
/** 入院給付金の通算支払限度（日） */
export const HOSPITAL_DAYS_LIMIT = 1_095;
/** 手術給付金の通算支払限度（回） */
export const SURGERY_COUNT_LIMIT = 12;

export const COVERAGE_TERMS: {
    value: CoverageTerm;
    label: string;
    description: string;
}[] = [
    { value: "y10", label: "10年", description: "10年ごとに更新。更新のたびに保険料は上がります" },
    { value: "y20", label: "20年", description: "20年ごとに更新。当面の保険料を抑えたいとき" },
    { value: "whole", label: "終身", description: "一生涯つづく保障。保険料は加入時のまま変わりません" },
];

export const PAYMENT_TERMS: {
    value: PaymentTerm;
    label: string;
    description: string;
}[] = [
    { value: "whole", label: "終身払", description: "生きているあいだ払い続ける。毎月の負担はいちばん軽い" },
    { value: "to60", label: "60歳払済", description: "60歳で払い終わる。毎月は高いが、老後の支出は無くなる" },
    { value: "to65", label: "65歳払済", description: "65歳で払い終わる。60歳払済より毎月はゆるやか" },
    { value: "full", label: "全期払", description: "保障の期間とおなじだけ払う（10年・20年で選べる唯一の方法）" },
];

export interface RiderDef {
    id: RiderId;
    name: string;
    summary: string;
    /** 受け取れる金額の説明（最大額の内訳に出す） */
    payoutNote: string;
}

export const RIDERS: RiderDef[] = [
    {
        id: "advanced",
        name: "先進医療特約",
        summary: "公的保険の対象外の先進医療にかかった技術料を、通算2,000万円まで実費で受け取れます",
        payoutNote: "技術料の実費・通算2,000万円まで",
    },
    {
        id: "cancer",
        name: "がん特約",
        summary: "がんと診断されたとき一時金50万円。2年に1回を限度に、再発でも受け取れます",
        payoutNote: "診断一時金50万円 × 2回まで",
    },
    {
        id: "outpatient",
        name: "通院特約",
        summary: "入院の前後の通院に、入院日額の60%を1回の入院につき30日まで",
        payoutNote: "入院日額の60% × 通算180日",
    },
    {
        id: "women",
        name: "女性疾病特約",
        summary: "乳がん・子宮筋腫など女性特有の病気の入院に、入院日額の50%を上乗せ",
        payoutNote: "入院日額の50%を上乗せ・通算540日",
    },
];

export const RIDER_BY_ID: Record<RiderId, RiderDef> = RIDERS.reduce(
    (acc, r) => ({ ...acc, [r.id]: r }),
    {} as Record<RiderId, RiderDef>,
);

/* ------------------------------------------------------------------ */
/* 料率（すべて目安のためのダミー係数）                                  */
/* ------------------------------------------------------------------ */

/** 30歳・男性・終身・終身払・手術20倍 のとき、入院日額1,000円あたりの月額 */
const BASE_PER_1000 = 330;

const TERM_FACTOR: Record<CoverageTerm, number> = { y10: 0.42, y20: 0.55, whole: 1 };

/** 1,000円日額あたりの特約月額（30歳基準） */
const RIDER_BASE_PER_1000: Record<RiderId, number> = {
    advanced: 0, // 日額に連動しない（下の FLAT を使う）
    cancer: 130,
    outpatient: 48,
    women: 80,
};
const RIDER_FLAT: Record<RiderId, number> = {
    advanced: 92,
    cancer: 0,
    outpatient: 0,
    women: 0,
};

function ageFactor(age: number): number {
    return Math.pow(1.043, age - 30);
}

function sexFactor(sex: Sex): number {
    return sex === "female" ? 0.95 : 1;
}

function surgeryFactor(multiplier: number): number {
    if (multiplier <= 10) return 0.94;
    if (multiplier <= 20) return 1;
    return 1.12;
}

/** その払込期間がその年齢で選べるか（払い終わりまで5年未満は取扱いなし、という想定） */
export function isPaymentTermAvailable(
    age: number,
    coverageTerm: CoverageTerm,
    paymentTerm: PaymentTerm,
): boolean {
    if (coverageTerm !== "whole") return paymentTerm === "full";
    if (paymentTerm === "full") return false;
    if (paymentTerm === "whole") return true;
    const end = paymentTerm === "to60" ? 60 : 65;
    return age <= end - 5;
}

/** 保障の期間から、選べる払込期間だけを返す */
export function availablePaymentTerms(age: number, coverageTerm: CoverageTerm): PaymentTerm[] {
    return PAYMENT_TERMS.map((t) => t.value).filter((t) =>
        isPaymentTermAvailable(age, coverageTerm, t),
    );
}

function paymentFactor(input: QuoteInput): number {
    if (input.coverageTerm !== "whole") return 1;
    if (input.paymentTerm === "whole") return 1;
    const end = input.paymentTerm === "to60" ? 60 : 65;
    const years = Math.max(end - input.age, 1);
    const raw = (WHOLE_PAY_ASSUMED_END_AGE - input.age) / years;
    // そのまま掛けると差が極端なので、7割だけ効かせる
    return 1 + 0.75 * (raw - 1);
}

/** 払込の回数（月数） */
export function paymentMonths(input: QuoteInput): number {
    if (input.coverageTerm === "y10") return 120;
    if (input.coverageTerm === "y20") return 240;
    if (input.paymentTerm === "to60") return Math.max(60 - input.age, 1) * 12;
    if (input.paymentTerm === "to65") return Math.max(65 - input.age, 1) * 12;
    return Math.max(WHOLE_PAY_ASSUMED_END_AGE - input.age, 1) * 12;
}

export interface PremiumLine {
    id: "main" | RiderId;
    label: string;
    monthly: number;
    note?: string;
}

export interface QuoteResult {
    /** 主契約＋特約の内訳 */
    lines: PremiumLine[];
    mainMonthly: number;
    ridersMonthly: number;
    monthlyTotal: number;
    months: number;
    totalPaid: number;
    /** 受け取れる可能性のある最大額（通算限度いっぱいまで使ったときの目安） */
    maxPayout: number;
    maxPayoutLines: { label: string; amount: number; note: string }[];
    /** 加入できる年齢の範囲内か */
    withinEntryAge: boolean;
    /** 選んだ払込期間がその年齢で選べるか */
    paymentTermAvailable: boolean;
}

function riderMonthly(id: RiderId, input: QuoteInput): number {
    const per1000 = RIDER_BASE_PER_1000[id] * (input.dailyAmount / 1000);
    const flat = RIDER_FLAT[id];
    const scaled =
        (per1000 + flat) *
        ageFactor(input.age) *
        sexFactor(input.sex) *
        TERM_FACTOR[input.coverageTerm] *
        paymentFactor(input);
    return Math.max(Math.round(scaled), 0);
}

/**
 * その特約を付けると月額がいくら増えるか（まだ選んでいなくても出せる）。
 * カードに「＋◯◯円/月」と出して、選ぶ前に判断できるようにするために使う。
 */
export function riderMonthlyPreview(id: RiderId, input: QuoteInput): number {
    return riderMonthly(id, input);
}

/**
 * 保障の期間を差し替えた条件を作る。
 * 10年・20年は全期払しか選べないので、払込の期間も一緒に整える。
 */
export function withCoverageTerm(input: QuoteInput, coverageTerm: CoverageTerm): QuoteInput {
    if (coverageTerm !== "whole") {
        return { ...input, coverageTerm, paymentTerm: "full" };
    }
    const keep = isPaymentTermAvailable(input.age, "whole", input.paymentTerm)
        ? input.paymentTerm
        : "whole";
    return { ...input, coverageTerm, paymentTerm: keep };
}

/** 年齢を変えたとき、選べなくなった払込の期間を整える */
export function withAge(input: QuoteInput, age: number): QuoteInput {
    if (isPaymentTermAvailable(age, input.coverageTerm, input.paymentTerm)) {
        return { ...input, age };
    }
    return { ...input, age, paymentTerm: input.coverageTerm === "whole" ? "whole" : "full" };
}

export function calcQuote(input: QuoteInput): QuoteResult {
    const withinEntryAge = input.age >= AGE_MIN && input.age <= AGE_MAX;
    const paymentTermAvailable = isPaymentTermAvailable(
        input.age,
        input.coverageTerm,
        input.paymentTerm,
    );

    const mainMonthly = Math.round(
        BASE_PER_1000 *
            (input.dailyAmount / 1000) *
            ageFactor(input.age) *
            sexFactor(input.sex) *
            TERM_FACTOR[input.coverageTerm] *
            surgeryFactor(input.surgeryMultiplier) *
            paymentFactor(input),
    );

    const activeRiders = input.riders.filter((id) => id !== "women" || input.sex === "female");

    const lines: PremiumLine[] = [
        {
            id: "main",
            label: "主契約（入院・手術）",
            monthly: mainMonthly,
            note: `入院日額 ${input.dailyAmount.toLocaleString("ja-JP")}円／手術 ${input.surgeryMultiplier}倍`,
        },
        ...activeRiders.map<PremiumLine>((id) => ({
            id,
            label: RIDER_BY_ID[id].name,
            monthly: riderMonthly(id, input),
            note: RIDER_BY_ID[id].payoutNote,
        })),
    ];

    const ridersMonthly = lines
        .filter((l) => l.id !== "main")
        .reduce((sum, l) => sum + l.monthly, 0);
    const monthlyTotal = mainMonthly + ridersMonthly;
    const months = paymentMonths(input);

    const maxPayoutLines: { label: string; amount: number; note: string }[] = [
        {
            label: "入院給付金",
            amount: input.dailyAmount * HOSPITAL_DAYS_LIMIT,
            note: `入院日額 × 通算${HOSPITAL_DAYS_LIMIT.toLocaleString("ja-JP")}日`,
        },
        {
            label: "手術給付金",
            amount: input.dailyAmount * input.surgeryMultiplier * SURGERY_COUNT_LIMIT,
            note: `入院日額 × ${input.surgeryMultiplier}倍 × 通算${SURGERY_COUNT_LIMIT}回`,
        },
        ...activeRiders.map((id) => ({
            label: RIDER_BY_ID[id].name,
            amount:
                id === "advanced"
                    ? 20_000_000
                    : id === "cancer"
                      ? 1_000_000
                      : id === "outpatient"
                        ? Math.round(input.dailyAmount * 0.6) * 180
                        : Math.round(input.dailyAmount * 0.5) * 540,
            note: RIDER_BY_ID[id].payoutNote,
        })),
    ];

    return {
        lines,
        mainMonthly,
        ridersMonthly,
        monthlyTotal,
        months,
        totalPaid: monthlyTotal * months,
        maxPayout: maxPayoutLines.reduce((sum, l) => sum + l.amount, 0),
        maxPayoutLines,
        withinEntryAge,
        paymentTermAvailable,
    };
}

export interface AgeProjection {
    /** いまから何年後に入るか */
    offsetYears: number;
    age: number;
    /** 入れない・その払込期間が選べない場合の理由。null なら試算できる */
    unavailableReason: string | null;
    monthlyTotal: number;
    totalPaid: number;
    monthlyDiff: number;
    totalDiff: number;
}

/** いま入る場合と、5年後・10年後に入る場合の比較 */
export function projectByAge(input: QuoteInput, offsets: number[] = [0, 5, 10]): AgeProjection[] {
    const base = calcQuote(input);
    return offsets.map((offsetYears) => {
        const age = input.age + offsetYears;
        if (age > AGE_MAX) {
            return {
                offsetYears,
                age,
                unavailableReason: `${AGE_MAX}歳を超えるため、この商品では新規のお申し込みができません`,
                monthlyTotal: 0,
                totalPaid: 0,
                monthlyDiff: 0,
                totalDiff: 0,
            };
        }
        if (!isPaymentTermAvailable(age, input.coverageTerm, input.paymentTerm)) {
            return {
                offsetYears,
                age,
                unavailableReason: "この年齢では、いま選んでいる払込の期間が選べません",
                monthlyTotal: 0,
                totalPaid: 0,
                monthlyDiff: 0,
                totalDiff: 0,
            };
        }
        const r = calcQuote({ ...input, age });
        return {
            offsetYears,
            age,
            unavailableReason: null,
            monthlyTotal: r.monthlyTotal,
            totalPaid: r.totalPaid,
            monthlyDiff: r.monthlyTotal - base.monthlyTotal,
            totalDiff: r.totalPaid - base.totalPaid,
        };
    });
}

/* ------------------------------------------------------------------ */
/* 表示用のラベル                                                       */
/* ------------------------------------------------------------------ */

export function coverageTermLabel(v: CoverageTerm): string {
    return COVERAGE_TERMS.find((t) => t.value === v)?.label ?? v;
}

export function paymentTermLabel(v: PaymentTerm): string {
    return PAYMENT_TERMS.find((t) => t.value === v)?.label ?? v;
}

export function sexLabel(v: Sex): string {
    return v === "female" ? "女性" : "男性";
}

/** 条件をひとことでまとめた文字列（比較・保存の見出しに使う） */
export function conditionSummary(input: QuoteInput): string {
    const riders = input.riders
        .filter((id) => id !== "women" || input.sex === "female")
        .map((id) => RIDER_BY_ID[id].name.replace("特約", ""));
    return [
        `${input.age}歳・${sexLabel(input.sex)}`,
        `日額${(input.dailyAmount / 1000).toLocaleString("ja-JP")}千円`,
        `${coverageTermLabel(input.coverageTerm)}／${paymentTermLabel(input.paymentTerm)}`,
        `手術${input.surgeryMultiplier}倍`,
        riders.length > 0 ? `特約：${riders.join("・")}` : "特約なし",
    ].join("／");
}

export function makeDefaultInput(): QuoteInput {
    return {
        age: 35,
        sex: "male",
        dailyAmount: 5_000,
        coverageTerm: "whole",
        paymentTerm: "whole",
        surgeryMultiplier: 20,
        riders: ["advanced"],
    };
}

"use client";

import * as React from "react";
import {
    Accordion,
    AccordionContent,
    AccordionItem,
    AccordionTrigger,
    Alert,
    AlertDescription,
    AlertTitle,
    AmountBreakdown,
    Badge,
    BottomActionBar,
    Button,
    Card,
    CardContent,
    CardDescription,
    CardHeader,
    CardTitle,
    CheckList,
    CheckboxCard,
    CheckboxCardGroup,
    Container,
    Delta,
    Dialog,
    DialogBody,
    DialogContent,
    DialogDescription,
    DialogFooter,
    DialogHeader,
    DialogTitle,
    EmptyState,
    Grid,
    HStack,
    Icon,
    Input,
    ListCard,
    PageHeader,
    RadioCard,
    RadioCardGroup,
    SegmentedControl,
    Separator,
    Skeleton,
    StatGroup,
    Table,
    TableBody,
    TableCaption,
    TableCell,
    TableHead,
    TableHeader,
    TableRow,
    ToastProvider,
    VStack,
    formatCurrency,
    useToast,
} from "@gunjo/ui";
import {
    IconAlertTriangle,
    IconBookmark,
    IconClipboardList,
    IconInfoCircle,
    IconLayoutColumns,
    IconPlus,
} from "@tabler/icons-react";

import {
    AGE_MAX,
    AGE_MIN,
    COVERAGE_TERMS,
    DAILY_MAX,
    DAILY_MIN,
    DAILY_STEP,
    PAYMENT_TERMS,
    RIDERS,
    SURGERY_MULTIPLIERS,
    calcQuote,
    conditionSummary,
    coverageTermLabel,
    isPaymentTermAvailable,
    makeDefaultInput,
    projectByAge,
    riderMonthlyPreview,
    withAge,
    withCoverageTerm,
    type CoverageTerm,
    type PaymentTerm,
    type QuoteInput,
    type RiderId,
    type Sex,
} from "./calc";
import { QuoteRangeField } from "./quote-range-field";
import { QuoteComparison, type ComparisonEntry } from "./quote-comparison";

const SAVED_STORAGE_KEY = "premium-quote:saved";
const MAX_COMPARISON_ENTRIES = 3;

interface SavedQuote {
    id: string;
    name: string;
    savedAt: string;
    input: QuoteInput;
    monthlyTotal: number;
}

/** 告知（健康状態の申告）で必ず聞かれることの例 */
const DISCLOSURE_ITEMS = [
    {
        id: "recent",
        label: "最近3か月以内に、医師の診察・検査・治療・投薬を受けたか",
        description: "健康診断や人間ドックで再検査をすすめられた場合も含みます",
    },
    {
        id: "history",
        label: "過去5年以内に、7日以上の入院や手術をしたか",
        description: "通院が続いている病気があるときも申告が必要です",
    },
    {
        id: "chronic",
        label: "いま治療中・経過観察中の病気があるか",
        description: "高血圧・糖尿病・うつ病などの継続通院も対象です",
    },
    {
        id: "pregnancy",
        label: "妊娠しているか（該当する場合）",
        description: "妊娠週数によって、お引き受けの条件が変わることがあります",
    },
];

function newId(): string {
    return `q-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 7)}`;
}

/** 万・億まるめの「ざっくりいくら」。金額の桁が大きいときの補助表示に使う */
function roughAmount(value: number): string {
    if (value >= 100_000_000) return `およそ${(value / 100_000_000).toFixed(1)}億円`;
    if (value >= 10_000) return `およそ${Math.round(value / 10_000).toLocaleString("ja-JP")}万円`;
    return `およそ${value.toLocaleString("ja-JP")}円`;
}

export function PremiumQuoteClient() {
    return (
        <ToastProvider>
            <PremiumQuoteScreen />
        </ToastProvider>
    );
}

function PremiumQuoteScreen() {
    const { showToast } = useToast();

    const [input, setInput] = React.useState<QuoteInput>(makeDefaultInput);
    const [comparison, setComparison] = React.useState<ComparisonEntry[]>([]);
    const [saved, setSaved] = React.useState<SavedQuote[]>([]);
    const [savedLoaded, setSavedLoaded] = React.useState(false);
    const [quoteName, setQuoteName] = React.useState("");
    const [saving, setSaving] = React.useState(false);
    const [applyOpen, setApplyOpen] = React.useState(false);
    const [applying, setApplying] = React.useState(false);
    const [checkedDisclosures, setCheckedDisclosures] = React.useState<string[]>([]);

    const result = React.useMemo(() => calcQuote(input), [input]);
    const projections = React.useMemo(() => projectByAge(input), [input]);

    /* --- 保存した見積もりの読み込み（ここだけ非同期なので読み込み中を出す） --- */
    React.useEffect(() => {
        let cancelled = false;
        const load = async () => {
            // localStorage は同期だが、実サービスでは保存先はサーバー。
            // 読み込み中の表示が出る形にしておく。
            await new Promise((resolve) => setTimeout(resolve, 450));
            if (cancelled) return;
            try {
                const raw = window.localStorage.getItem(SAVED_STORAGE_KEY);
                setSaved(raw ? (JSON.parse(raw) as SavedQuote[]) : []);
            } catch {
                setSaved([]);
            }
            setSavedLoaded(true);
        };
        void load();
        return () => {
            cancelled = true;
        };
    }, []);

    const persist = React.useCallback((next: SavedQuote[]) => {
        setSaved(next);
        try {
            window.localStorage.setItem(SAVED_STORAGE_KEY, JSON.stringify(next));
        } catch {
            // 保存できなくても試算自体は続けられる
        }
    }, []);

    /* --- 値が続けて変わるときの読み上げ。落ち着いてから1回だけ知らせる --- */
    const [announcement, setAnnouncement] = React.useState("");
    React.useEffect(() => {
        const timer = window.setTimeout(() => {
            setAnnouncement(
                `毎月の保険料 ${formatCurrency(result.monthlyTotal)}、` +
                    `払込の総額 ${formatCurrency(result.totalPaid)}、` +
                    `受け取れる可能性のある最大額 ${formatCurrency(result.maxPayout)}。目安です。`,
            );
        }, 800);
        return () => window.clearTimeout(timer);
    }, [result.monthlyTotal, result.totalPaid, result.maxPayout]);

    /* --- 操作 --- */
    const handleAgeChange = (age: number) => setInput((prev) => withAge(prev, age));
    const handleCoverageTermChange = (value: string) =>
        setInput((prev) => withCoverageTerm(prev, value as CoverageTerm));
    const handlePaymentTermChange = (value: string) =>
        setInput((prev) => ({ ...prev, paymentTerm: value as PaymentTerm }));
    const handleSexChange = (value: string) =>
        setInput((prev) => ({ ...prev, sex: value as Sex }));

    const addToComparison = () => {
        if (comparison.length >= MAX_COMPARISON_ENTRIES) {
            // ToastType は info / success / error の3つだけで warning が無いため info で出す
            showToast({
                message: `並べられるのは${MAX_COMPARISON_ENTRIES}案までです`,
                type: "info",
                description: "見比べたい案を残して、いらない案を外してください",
            });
            return;
        }
        const entry: ComparisonEntry = {
            id: newId(),
            name: `案${comparison.length + 1}`,
            input,
            result,
        };
        setComparison((prev) => [...prev, entry]);
        showToast({ message: `${entry.name}として並べました`, type: "success" });
    };

    const saveQuote = async () => {
        const name = quoteName.trim() || `${coverageTermLabel(input.coverageTerm)}の見積もり`;
        setSaving(true);
        await new Promise((resolve) => setTimeout(resolve, 600));
        persist([
            {
                id: newId(),
                name,
                savedAt: new Date().toISOString(),
                input,
                monthlyTotal: result.monthlyTotal,
            },
            ...saved,
        ]);
        setQuoteName("");
        setSaving(false);
        showToast({
            message: `「${name}」を保存しました`,
            type: "success",
            description: "あとからこの条件を呼び出せます",
        });
    };

    const restoreQuote = (quote: SavedQuote) => {
        setInput(quote.input);
        showToast({ message: `「${quote.name}」の条件に戻しました`, type: "info" });
    };

    const proceedToApplication = async () => {
        setApplying(true);
        await new Promise((resolve) => setTimeout(resolve, 900));
        setApplying(false);
        setApplyOpen(false);
        setCheckedDisclosures([]);
        showToast({
            message: "お申し込み手続きに進みます",
            type: "info",
            description: "次の画面で告知（健康状態の申告）を入力します",
        });
    };

    const availableRiders = RIDERS.filter(
        (rider) => rider.id !== "women" || input.sex === "female",
    );
    const selectedRiders = input.riders.filter(
        (id) => id !== "women" || input.sex === "female",
    );

    const monthlyDisplay = formatCurrency(result.monthlyTotal);
    const disclosureAllChecked = checkedDisclosures.length === DISCLOSURE_ITEMS.length;

    return (
        <div className="flex min-h-dvh flex-col bg-background pb-28 md:pb-8">
            <PageHeader
                title="医療保険の保険料をためす"
                subtitle="条件を動かすと、毎月いくらかがその場で変わります"
                actions={
                    <Badge variant="outline" icon={<Icon icon={IconInfoCircle} size="xs" decorative />}>
                        試算は目安
                    </Badge>
                }
            />

            {/* 値が続けて変わるので、落ち着いてから1回だけ読み上げる */}
            <div role="status" aria-live="polite" className="sr-only">
                {announcement}
            </div>

            <Container size="xl" className="w-full flex-1 py-6">
                <VStack gap={6}>
                    <Alert variant="info" icon={<IconInfoCircle />}>
                        <AlertTitle>ここに出る金額はすべて目安です</AlertTitle>
                        <AlertDescription>
                            実際の保険料は、健康状態の告知の内容と保険会社の審査によって決まります。
                            条件によっては、保険料が上がる・一部の保障が付けられない・お引き受けできないこともあります。
                        </AlertDescription>
                    </Alert>

                    <Grid cols={{ base: 1, lg: 2 }} gap={6} className="items-start">
                        {/* ------------------- 左: 条件 ------------------- */}
                        <VStack gap={4} className="min-w-0">
                            <Card>
                                <CardHeader>
                                    <CardTitle as="h2">あなたのこと</CardTitle>
                                    <CardDescription>
                                        保険料は年齢と性別で変わります
                                    </CardDescription>
                                </CardHeader>
                                <CardContent>
                                    <VStack gap={5}>
                                        <QuoteRangeField
                                            label="年齢"
                                            value={input.age}
                                            onValueChange={handleAgeChange}
                                            min={AGE_MIN}
                                            max={AGE_MAX}
                                            step={1}
                                            minLabel={`${AGE_MIN}歳`}
                                            maxLabel={`${AGE_MAX}歳`}
                                            formatValue={(v) => `${v}歳`}
                                            description={`このプランに申し込めるのは${AGE_MIN}歳から${AGE_MAX}歳までです`}
                                        />
                                        <div className="flex flex-col gap-2">
                                            <span
                                                id="sex-label"
                                                className="text-sm font-medium leading-none"
                                            >
                                                性別
                                            </span>
                                            <SegmentedControl
                                                aria-labelledby="sex-label"
                                                size="lg"
                                                value={input.sex}
                                                onValueChange={handleSexChange}
                                                options={[
                                                    { value: "male", label: "男性" },
                                                    { value: "female", label: "女性" },
                                                ]}
                                            />
                                            <p className="text-xs text-muted-foreground">
                                                女性疾病特約は、性別が女性のときだけ選べます
                                            </p>
                                        </div>
                                    </VStack>
                                </CardContent>
                            </Card>

                            <Card>
                                <CardHeader>
                                    <CardTitle as="h2">保障の中身</CardTitle>
                                    <CardDescription>
                                        入院1日あたりいくら受け取るか、手術のときは日額の何倍か
                                    </CardDescription>
                                </CardHeader>
                                <CardContent>
                                    <VStack gap={5}>
                                        <QuoteRangeField
                                            label="入院日額"
                                            value={input.dailyAmount}
                                            onValueChange={(dailyAmount) =>
                                                setInput((prev) => ({ ...prev, dailyAmount }))
                                            }
                                            min={DAILY_MIN}
                                            max={DAILY_MAX}
                                            step={DAILY_STEP}
                                            minLabel={formatCurrency(DAILY_MIN)}
                                            maxLabel={formatCurrency(DAILY_MAX)}
                                            formatValue={(v) => `${formatCurrency(v)}／日`}
                                            inputClassName="w-32"
                                            description="入院1日につき受け取る金額。1,000円きざみで選べます"
                                        />
                                        <div className="flex flex-col gap-2">
                                            <span
                                                id="surgery-multiplier-label"
                                                className="text-sm font-medium leading-none"
                                            >
                                                手術給付の倍率
                                            </span>
                                            <SegmentedControl
                                                aria-labelledby="surgery-multiplier-label"
                                                size="lg"
                                                value={String(input.surgeryMultiplier)}
                                                onValueChange={(value) =>
                                                    setInput((prev) => ({
                                                        ...prev,
                                                        surgeryMultiplier: Number(value),
                                                    }))
                                                }
                                                options={SURGERY_MULTIPLIERS.map((m) => ({
                                                    value: String(m),
                                                    label: `${m}倍`,
                                                }))}
                                            />
                                            <p className="text-xs text-muted-foreground">
                                                手術1回につき、入院日額の
                                                {input.surgeryMultiplier}倍（
                                                {formatCurrency(
                                                    input.dailyAmount * input.surgeryMultiplier,
                                                )}
                                                ）を受け取ります
                                            </p>
                                        </div>
                                    </VStack>
                                </CardContent>
                            </Card>

                            <Card>
                                <CardHeader>
                                    <CardTitle as="h2" id="coverage-term-heading">
                                        保障の期間
                                    </CardTitle>
                                    <CardDescription>
                                        いつまで守るか。金額は、いまの条件でこの期間を選んだときの毎月の保険料です
                                    </CardDescription>
                                </CardHeader>
                                <CardContent>
                                    <RadioCardGroup
                                        aria-labelledby="coverage-term-heading"
                                        value={input.coverageTerm}
                                        onValueChange={handleCoverageTermChange}
                                        className="grid gap-2"
                                    >
                                        {COVERAGE_TERMS.map((term) => {
                                            const preview = calcQuote(
                                                withCoverageTerm(input, term.value),
                                            );
                                            return (
                                                <RadioCard
                                                    key={term.value}
                                                    value={term.value}
                                                    title={term.label}
                                                    description={term.description}
                                                    price={
                                                        <span className="tabular-nums">
                                                            {formatCurrency(preview.monthlyTotal)}
                                                            <span className="text-xs font-normal text-muted-foreground">
                                                                ／月
                                                            </span>
                                                        </span>
                                                    }
                                                />
                                            );
                                        })}
                                    </RadioCardGroup>
                                </CardContent>
                            </Card>

                            <Card>
                                <CardHeader>
                                    <CardTitle as="h2" id="payment-term-heading">
                                        払込の期間
                                    </CardTitle>
                                    <CardDescription>
                                        いつまで払うか。早く払い終えるほど毎月は上がり、払込の総額は下がります
                                    </CardDescription>
                                </CardHeader>
                                <CardContent>
                                    <RadioCardGroup
                                        aria-labelledby="payment-term-heading"
                                        value={input.paymentTerm}
                                        onValueChange={handlePaymentTermChange}
                                        className="grid gap-2"
                                    >
                                        {PAYMENT_TERMS.map((term) => {
                                            const usable = isPaymentTermAvailable(
                                                input.age,
                                                input.coverageTerm,
                                                term.value,
