                                            const preview = usable
                                                ? calcQuote({ ...input, paymentTerm: term.value })
                                                : null;
                                            return (
                                                <RadioCard
                                                    key={term.value}
                                                    value={term.value}
                                                    title={term.label}
                                                    description={term.description}
                                                    disabled={!usable}
                                                    disabledReason={
                                                        term.value === "full"
                                                            ? "全期払は、保障の期間が10年・20年のときだけ選べます"
                                                            : input.coverageTerm !== "whole"
                                                              ? "保障の期間が10年・20年のときは、払込も同じ期間（全期払）になります"
                                                              : `${input.age}歳では、払い終わりまでが短すぎて選べません`
                                                    }
                                                    price={
                                                        preview ? (
                                                            <span className="tabular-nums">
                                                                {formatCurrency(
                                                                    preview.monthlyTotal,
                                                                )}
                                                                <span className="text-xs font-normal text-muted-foreground">
                                                                    ／月
                                                                </span>
                                                            </span>
                                                        ) : (
                                                            <span className="text-sm font-normal text-muted-foreground">
                                                                選べません
                                                            </span>
                                                        )
                                                    }
                                                    highlight={
                                                        preview
                                                            ? `払込の総額 ${roughAmount(preview.totalPaid)}`
                                                            : undefined
                                                    }
                                                />
                                            );
                                        })}
                                    </RadioCardGroup>
                                </CardContent>
                            </Card>

                            <Card>
                                <CardHeader>
                                    <CardTitle as="h2" id="riders-heading">
                                        付ける特約
                                    </CardTitle>
                                    <CardDescription>
                                        右の金額は、その特約を足したときに毎月ふえる分です
                                    </CardDescription>
                                </CardHeader>
                                <CardContent>
                                    <CheckboxCardGroup
                                        aria-labelledby="riders-heading"
                                        value={selectedRiders}
                                        onValueChange={(riders) =>
                                            setInput((prev) => ({
                                                ...prev,
                                                riders: riders as RiderId[],
                                            }))
                                        }
                                        className="grid gap-2"
                                    >
                                        {RIDERS.map((rider) => {
                                            const selectable =
                                                rider.id !== "women" || input.sex === "female";
                                            const delta = riderMonthlyPreview(rider.id, input);
                                            return (
                                                <CheckboxCard
                                                    key={rider.id}
                                                    value={rider.id}
                                                    title={rider.name}
                                                    description={rider.summary}
                                                    disabled={!selectable}
                                                    disabledReason="女性疾病特約は、性別が女性のときだけ付けられます"
                                                    price={
                                                        selectable ? (
                                                            <span className="tabular-nums">
                                                                ＋{formatCurrency(delta)}
                                                                <span className="text-xs font-normal text-muted-foreground">
                                                                    ／月
                                                                </span>
                                                            </span>
                                                        ) : (
                                                            <span className="text-sm font-normal text-muted-foreground">
                                                                付けられません
                                                            </span>
                                                        )
                                                    }
                                                />
                                            );
                                        })}
                                    </CheckboxCardGroup>
                                    {availableRiders.length < RIDERS.length && (
                                        <p className="mt-3 text-xs text-muted-foreground">
                                            性別を女性にすると、女性疾病特約が選べるようになります。
                                        </p>
                                    )}
                                </CardContent>
                            </Card>
                        </VStack>

                        {/* ------------------- 右: 結果 ------------------- */}
                        <VStack gap={4} className="min-w-0 lg:sticky lg:top-24">
                            <Card>
                                <CardHeader>
                                    <CardTitle as="h2">いまの条件だと</CardTitle>
                                    <CardDescription>{conditionSummary(input)}</CardDescription>
                                </CardHeader>
                                <CardContent>
                                    <VStack gap={5}>
                                        <div className="rounded-lg border bg-muted/40 p-4">
                                            <p className="text-sm text-muted-foreground">
                                                毎月の保険料（目安）
                                            </p>
                                            <p className="mt-1 text-4xl font-bold tabular-nums tracking-tight">
                                                {monthlyDisplay}
                                            </p>
                                            <p className="mt-1 text-sm text-muted-foreground">
                                                主契約 {formatCurrency(result.mainMonthly)} ＋ 特約{" "}
                                                {formatCurrency(result.ridersMonthly)}
                                            </p>
                                        </div>

                                        <StatGroup
                                            cols={{ base: 1, sm: 2 }}
                                            card={false}
                                            items={[
                                                {
                                                    label: "払込の総額（目安）",
                                                    value: formatCurrency(result.totalPaid),
                                                    hint: `毎月 ${monthlyDisplay} × ${result.months.toLocaleString("ja-JP")}回`,
                                                },
                                                {
                                                    label: "受け取れる可能性のある最大額",
                                                    value: formatCurrency(result.maxPayout),
                                                    hint: "通算の限度いっぱいまで使ったとき",
                                                },
                                            ]}
                                        />

                                        <Separator />

                                        <div>
                                            <h3 className="mb-2 text-sm font-semibold">
                                                保険料の内訳（月額）
                                            </h3>
                                            <AmountBreakdown
                                                lines={result.lines.map((line) => ({
                                                    label: line.label,
                                                    amount: line.monthly,
                                                    note: line.note,
                                                }))}
                                                total={{
                                                    label: "毎月の保険料",
                                                    amount: result.monthlyTotal,
                                                }}
                                                formula="毎月の保険料 = 主契約 ＋ 付けた特約の合計"
                                            />
                                            {selectedRiders.length === 0 && (
                                                <p className="mt-2 text-xs text-muted-foreground">
                                                    特約を選ぶと、この内訳に行がふえます。
                                                </p>
                                            )}
                                        </div>

                                        <Accordion type="single" collapsible>
                                            <AccordionItem value="max-payout">
                                                <AccordionTrigger>
                                                    受け取れる最大額のうちわけを見る
                                                </AccordionTrigger>
                                                <AccordionContent>
                                                    <AmountBreakdown
                                                        lines={result.maxPayoutLines.map((l) => ({
                                                            label: l.label,
                                                            amount: l.amount,
                                                            note: l.note,
                                                        }))}
                                                        total={{
                                                            label: "受け取れる可能性のある最大額",
                                                            amount: result.maxPayout,
                                                        }}
                                                    />
                                                    <p className="mt-3 text-xs text-muted-foreground">
                                                        これは限度いっぱいまで受け取った場合の合計で、
                                                        実際にこの金額を受け取れることを約束するものではありません。
                                                    </p>
                                                </AccordionContent>
                                            </AccordionItem>
                                        </Accordion>
                                    </VStack>
                                </CardContent>
                            </Card>

                            <Card>
                                <CardHeader>
                                    <CardTitle as="h2" id="age-projection-heading">
                                        いま入る場合と、あとで入る場合
                                    </CardTitle>
                                    <CardDescription>
                                        同じ保障でも、入る年齢が上がると毎月の保険料は上がります
                                    </CardDescription>
                                </CardHeader>
                                <CardContent>
                                    <Table aria-labelledby="age-projection-heading">
                                        <TableHeader>
                                            <TableRow>
                                                <TableHead scope="col">入るタイミング</TableHead>
                                                <TableHead scope="col" className="text-right">
                                                    毎月
                                                </TableHead>
                                                <TableHead scope="col" className="text-right">
                                                    いまとの差
                                                </TableHead>
                                                <TableHead scope="col" className="text-right">
                                                    払込の総額
                                                </TableHead>
                                            </TableRow>
                                        </TableHeader>
                                        <TableBody>
                                            {projections.map((p) => (
                                                <TableRow key={p.offsetYears}>
                                                    <TableHead scope="row" className="h-auto py-3 font-medium">
                                                        {p.offsetYears === 0
                                                            ? `いま（${p.age}歳）`
                                                            : `${p.offsetYears}年後（${p.age}歳）`}
                                                    </TableHead>
                                                    {p.unavailableReason ? (
                                                        <TableCell colSpan={3} className="py-3 text-sm text-muted-foreground">
                                                            {p.unavailableReason}
                                                        </TableCell>
                                                    ) : (
                                                        <>
                                                            <TableCell className="py-3 text-right tabular-nums">
                                                                {formatCurrency(p.monthlyTotal)}
                                                            </TableCell>
                                                            <TableCell className="py-3 text-right">
                                                                {p.offsetYears === 0 ? (
                                                                    <span className="text-muted-foreground">
                                                                        —
                                                                    </span>
                                                                ) : (
                                                                    <Delta
                                                                        value={p.monthlyDiff}
                                                                        format={(v) =>
                                                                            formatCurrency(v, {
                                                                                signed: true,
                                                                            })
                                                                        }
                                                                        tones={{
                                                                            positive: "destructive",
                                                                            negative: "success",
                                                                        }}
                                                                        labels={{
                                                                            positive: "高くなる",
                                                                            negative: "安くなる",
                                                                            zero: "変わらない",
                                                                        }}
                                                                    />
                                                                )}
                                                            </TableCell>
                                                            <TableCell className="py-3 text-right tabular-nums">
                                                                {formatCurrency(p.totalPaid)}
                                                            </TableCell>
                                                        </>
                                                    )}
                                                </TableRow>
                                            ))}
                                        </TableBody>
                                        <TableCaption className="px-4 text-left text-xs">
                                            あとから入ると、保障が始まるまでの期間は守られません。
                                            健康状態によっては、そのとき入れないこともあります。
                                        </TableCaption>
                                    </Table>
                                </CardContent>
                            </Card>
                        </VStack>
                    </Grid>

                    {/* ------------------- 他の入り方との比較 ------------------- */}
                    <Card>
                        <CardHeader>
                            <div className="flex flex-wrap items-start justify-between gap-3">
                                <div>
                                    <CardTitle as="h2" id="comparison-heading">
                                        他の入り方と見比べる
                                    </CardTitle>
                                    <CardDescription>
                                        条件を変えては「この条件を並べる」を押すと、{MAX_COMPARISON_ENTRIES}
                                        案まで横に並べられます
                                    </CardDescription>
                                </div>
                                <Button
                                    variant="outline"
                                    onClick={addToComparison}
                                    disabled={comparison.length >= MAX_COMPARISON_ENTRIES}
                                >
                                    <Icon icon={IconPlus} size="sm" decorative />
                                    この条件を並べる
                                </Button>
                            </div>
                        </CardHeader>
                        <CardContent>
                            {comparison.length === 0 ? (
                                <EmptyState
                                    headingLevel={3}
                                    icon={<Icon icon={IconLayoutColumns} size="xl" decorative />}
                                    title="まだ並べた案はありません"
                                    description="入院日額を下げて特約を厚くする、払込を60歳で終わらせる、といった条件を作って並べてみてください。"
                                    action={
                                        <Button variant="outline" onClick={addToComparison}>
                                            いまの条件を並べる
                                        </Button>
                                    }
                                />
                            ) : (
                                <QuoteComparison
                                    entries={comparison}
                                    labelledById="comparison-heading"
                                    onRemove={(id) =>
                                        setComparison((prev) => prev.filter((e) => e.id !== id))
                                    }
                                />
                            )}
                        </CardContent>
                    </Card>

                    {/* ------------------- 見積もりの保存 ------------------- */}
                    <Card>
                        <CardHeader>
                            <CardTitle as="h2" id="saved-heading">
                                この条件に名前を付けて残す
                            </CardTitle>
                            <CardDescription>
                                あとで開くと、そのときの条件に戻せます
                            </CardDescription>
                        </CardHeader>
                        <CardContent>
                            <VStack gap={4}>
                                {/* Input の className は <input> 自体に付くため、
                                    幅の調整はこちらのラッパーで持つ */}
                                <div className="flex flex-col gap-3">
                                    <div className="max-w-md">
                                        <Input
                                            label="見積もりの名前"
                                            description="例：日額1万円・終身・60歳払済"
                                            value={quoteName}
                                            onChange={(e) => setQuoteName(e.target.value)}
                                            maxLength={40}
                                            showCount
                                        />
                                    </div>
                                    <Button
                                        onClick={saveQuote}
                                        loading={saving}
                                        className="self-start"
                                    >
                                        <Icon icon={IconBookmark} size="sm" decorative />
                                        保存する
                                    </Button>
                                </div>

                                <Separator />

                                {!savedLoaded ? (
                                    <div aria-busy="true" aria-live="polite" className="flex flex-col gap-2">
                                        <span className="sr-only">保存した見積もりを読み込んでいます</span>
                                        {[0, 1].map((i) => (
                                            <div
                                                key={i}
                                                className="flex items-center gap-3 rounded-lg border p-4"
                                            >
                                                <Skeleton shape="circle" className="h-9 w-9" />
                                                <div className="flex flex-1 flex-col gap-2">
                                                    <Skeleton shape="text" className="h-4 w-2/5" />
                                                    <Skeleton shape="text" className="h-3 w-4/5" />
                                                </div>
                                                <Skeleton shape="rectangle" className="h-5 w-20" />
                                            </div>
                                        ))}
                                    </div>
                                ) : saved.length === 0 ? (
                                    <EmptyState
                                        headingLevel={3}
                                        icon={<Icon icon={IconBookmark} size="xl" decorative />}
                                        title="保存した見積もりはまだありません"
                                        description="名前を付けて保存すると、ここに並びます。"
                                    />
                                ) : (
                                    <ul aria-labelledby="saved-heading" className="flex flex-col gap-2">
                                        {saved.map((quote) => (
                                            <li key={quote.id}>
                                                <ListCard
                                                    leading={
                                                        <Icon
                                                            icon={IconBookmark}
                                                            size="md"
                                                            decorative
                                                        />
                                                    }
                                                    title={quote.name}
                                                    description={conditionSummary(quote.input)}
                                                    meta={
                                                        <span className="tabular-nums">
                                                            {formatCurrency(quote.monthlyTotal)}／月
                                                        </span>
                                                    }
                                                    onSelect={() => restoreQuote(quote)}
                                                />
                                            </li>
                                        ))}
                                    </ul>
                                )}
                            </VStack>
                        </CardContent>
                    </Card>

                    {/* ------------------- 申し込みへ ------------------- */}
                    <Card>
                        <CardHeader>
                            <CardTitle as="h2">申し込みに進む前に</CardTitle>
                        </CardHeader>
                        <CardContent>
                            <VStack gap={4}>
                                <Alert variant="warning" icon={<IconAlertTriangle />}>
                                    <AlertTitle>告知（健康状態の申告）が必要です</AlertTitle>
                                    <AlertDescription>
                                        申し込みのときは、いまの健康状態や過去の入院・手術について
                                        ありのままを申告します。ここで出ている
                                        {monthlyDisplay}
                                        は告知の前の目安なので、審査の結果、保険料が上がったり、
                                        お引き受けできないことがあります。
                                    </AlertDescription>
                                </Alert>
                                <HStack gap={3} wrap>
                                    <Button size="lg" onClick={() => setApplyOpen(true)}>
                                        <Icon icon={IconClipboardList} size="sm" decorative />
                                        告知の内容を確かめて進む
                                    </Button>
                                    <Button size="lg" variant="ghost" onClick={saveQuote} loading={saving}>
                                        まだ決めない（保存だけする）
                                    </Button>
                                </HStack>
                            </VStack>
                        </CardContent>
                    </Card>

                    <p className="pb-4 text-xs leading-relaxed text-muted-foreground">
                        このページの金額はすべて試算上の目安で、特定の保険会社・商品のものではありません。
                        実際のご契約内容・保険料・お引き受けの可否は、告知いただいた健康状態と保険会社の審査によって決まります。
                        保障の詳しい条件は、ご契約のしおり・約款でご確認ください。
                    </p>
                </VStack>
            </Container>

            {/* モバイルでは下に貼り付いて、いくらかを見失わないようにする */}
            <BottomActionBar
                className="md:hidden"
                actions={
                    <Button onClick={() => setApplyOpen(true)} size="touch">
                        申し込みに進む
                    </Button>
                }
            >
                <div>
                    <p className="text-xs text-muted-foreground">毎月の保険料（目安）</p>
                    <p className="text-lg font-bold tabular-nums leading-tight">
                        {monthlyDisplay}
                    </p>
                </div>
            </BottomActionBar>

            <Dialog open={applyOpen} onOpenChange={setApplyOpen}>
                <DialogContent className="max-h-[90dvh] overflow-y-auto">
                    <DialogHeader>
                        <DialogTitle>申し込みの前に、告知の内容を確かめてください</DialogTitle>
                        <DialogDescription>
                            次の画面で、以下のことを申告していただきます。
                            事実と違う申告をすると、保険金をお支払いできなかったり、
                            ご契約が解除になることがあります。
                        </DialogDescription>
                    </DialogHeader>
                    <DialogBody>
                        <VStack gap={4}>
                            <CheckList
                                items={DISCLOSURE_ITEMS.map((item) => ({
                                    id: item.id,
                                    label: item.label,
                                    description: item.description,
                                    checked: checkedDisclosures.includes(item.id),
                                }))}
                                onCheckedChange={(id, checked) =>
                                    setCheckedDisclosures((prev) =>
                                        checked
                                            ? [...prev, id]
                                            : prev.filter((existing) => existing !== id),
                                    )
                                }
                            />
                            <p className="text-xs text-muted-foreground">
                                いま試算している条件：{conditionSummary(input)}／毎月{" "}
                                {monthlyDisplay}
                                （目安）
                            </p>
                        </VStack>
                    </DialogBody>
                    <DialogFooter>
                        <Button variant="ghost" onClick={() => setApplyOpen(false)}>
                            試算に戻る
                        </Button>
                        <Button
                            onClick={proceedToApplication}
                            loading={applying}
                            disabled={!disclosureAllChecked}
                        >
                            {disclosureAllChecked
                                ? "申し込み手続きに進む"
                                : `あと${DISCLOSURE_ITEMS.length - checkedDisclosures.length}項目の確認が必要`}
                        </Button>
                    </DialogFooter>
                </DialogContent>
            </Dialog>
        </div>
    );
}

"use client";

import * as React from "react";
import {
    Badge,
    Button,
    Icon,
    Table,
    TableBody,
    TableCaption,
    TableCell,
    TableHead,
    TableHeader,
    TableRow,
    formatCurrency,
} from "@gunjo/ui";
import { IconTrash } from "@tabler/icons-react";

import {
    RIDER_BY_ID,
    coverageTermLabel,
    paymentTermLabel,
    sexLabel,
    type QuoteInput,
    type QuoteResult,
} from "./calc";

export interface ComparisonEntry {
    id: string;
    name: string;
    input: QuoteInput;
    result: QuoteResult;
}

interface Row {
    key: string;
    header: string;
    render: (entry: ComparisonEntry) => React.ReactNode;
    /** 数字の列を右寄せ・等幅にする */
    numeric?: boolean;
}

const ROWS: Row[] = [
    {
        key: "monthly",
        header: "毎月の保険料",
        numeric: true,
        render: (e) => formatCurrency(e.result.monthlyTotal),
    },
    {
        key: "total",
        header: "払込の総額",
        numeric: true,
        render: (e) => formatCurrency(e.result.totalPaid),
    },
    {
        key: "max",
        header: "受け取れる最大額",
        numeric: true,
        render: (e) => formatCurrency(e.result.maxPayout),
    },
    {
        key: "person",
        header: "年齢・性別",
        render: (e) => `${e.input.age}歳・${sexLabel(e.input.sex)}`,
    },
    {
        key: "daily",
        header: "入院日額",
        numeric: true,
        render: (e) => formatCurrency(e.input.dailyAmount),
    },
    {
        key: "coverage",
        header: "保障の期間",
        render: (e) => coverageTermLabel(e.input.coverageTerm),
    },
    {
        key: "payment",
        header: "払込の期間",
        render: (e) => paymentTermLabel(e.input.paymentTerm),
    },
    {
        key: "surgery",
        header: "手術給付の倍率",
        numeric: true,
        render: (e) => `${e.input.surgeryMultiplier}倍`,
    },
    {
        key: "riders",
        header: "付ける特約",
        render: (e) => {
            const names = e.input.riders
                .filter((id) => id !== "women" || e.input.sex === "female")
                .map((id) => RIDER_BY_ID[id].name);
            return names.length > 0 ? names.join("、") : "なし";
        },
    },
];

export interface QuoteComparisonProps {
    entries: ComparisonEntry[];
    onRemove: (id: string) => void;
    /** 表の見出しに使う id（見出し要素と結びつける） */
    labelledById: string;
}

/**
 * ためた案を横に並べて見比べる表。
 *
 * 案が列・項目が行の「転置した比較表」。@gunjo/ui の DataTable は
 * 1行＝1レコードの並び替え・ページングつきの表なので方向が合わず、
 * ScheduleGrid は時間割・シフト表向けの role="grid" なので、
 * ここは素の Table プリミティブ（thead/th scope）で組んでいる。
 */
export function QuoteComparison({ entries, onRemove, labelledById }: QuoteComparisonProps) {
    const cheapestMonthly = React.useMemo(
        () => Math.min(...entries.map((e) => e.result.monthlyTotal)),
        [entries],
    );

    // Table 自体が overflow-auto + contain:paint のスクロール箱を内蔵しているので、
    // 外側でスクロールを二重にかけない。列が増えたら箱の中で横スクロールする。
    return (
        <Table aria-labelledby={labelledById} className="min-w-[560px]">
            <TableHeader>
                <TableRow>
                    <TableHead scope="col" className="w-36 min-w-32">
                        項目
                    </TableHead>
                    {entries.map((entry) => (
                        <TableHead key={entry.id} scope="col" className="min-w-40 align-top">
                            <div className="flex flex-col items-start gap-1 py-2">
                                <span className="whitespace-normal font-semibold text-foreground">
                                    {entry.name}
                                </span>
                                {entries.length > 1 &&
                                    entry.result.monthlyTotal === cheapestMonthly && (
                                        <Badge variant="success" size="sm">
                                            毎月がいちばん安い
                                        </Badge>
                                    )}
                                <Button
                                    variant="ghost"
                                    size="sm"
                                    className="px-1 text-xs font-normal text-muted-foreground"
                                    onClick={() => onRemove(entry.id)}
                                >
                                    <Icon icon={IconTrash} size="sm" decorative />
                                    <span>この案を外す</span>
                                    <span className="sr-only">（{entry.name}）</span>
                                </Button>
                            </div>
                        </TableHead>
                    ))}
                </TableRow>
            </TableHeader>
            <TableBody>
                {ROWS.map((row) => (
                    <TableRow key={row.key}>
                        <TableHead
                            scope="row"
                            className="h-auto py-3 align-top text-xs font-medium text-muted-foreground"
                        >
                            {row.header}
                        </TableHead>
                        {entries.map((entry) => (
                            <TableCell
                                key={entry.id}
                                className={
                                    row.numeric
                                        ? "whitespace-nowrap py-3 align-top tabular-nums"
                                        : "py-3 align-top"
                                }
                            >
                                {row.render(entry)}
                            </TableCell>
                        ))}
                    </TableRow>
                ))}
            </TableBody>
            <TableCaption className="px-4 text-left text-xs">
                ためた案の比較。金額はすべて目安で、実際の保険料は告知と審査によって変わります。
            </TableCaption>
        </Table>
    );
}

"use client";

import * as React from "react";
import { Button, Icon, Input, Label, Slider, cn } from "@gunjo/ui";
import { IconMinus, IconPlus } from "@tabler/icons-react";

export interface QuoteRangeFieldProps {
    /** 見出し（つまみと直接入力の両方をまとめた名前） */
    label: string;
    value: number;
    onValueChange: (value: number) => void;
    min: number;
    max: number;
    step: number;
    /** 補足。つまみと直接入力の両方に aria-describedby でつながる */
    description?: string;
    /** 表示と読み上げ用の整形。読み上げは aria-valuetext に入る */
    formatValue: (value: number) => string;
    /** 目盛りの左端・右端に出すテキスト */
    minLabel?: string;
    maxLabel?: string;
    /** 直接入力欄の幅 */
    inputClassName?: string;
    className?: string;
}

function clamp(value: number, min: number, max: number): number {
    return Math.min(max, Math.max(min, value));
}

/**
 * 「つまみでも直接の指定でもできる」入力。
 *
 * @gunjo/ui には Slider（label・formatValue・値の output つき）と NumberInput
 * （± ボタンつきの数値入力）が別々にあるが、「ひとつの値をふたつのコントロールで
 * 編集する」形は無いので、ここで組んでいる。
 *
 * 数値入力に NumberInput を使わなかった理由:
 * NumberInput は1文字打つたびに min / max で値を丸めるため、min が2桁以上の欄
 * （年齢 min=18、入院日額 min=5000）では直接入力が事実上できない。
 * 「45」と打つと 4 の時点で 18 に丸められ、続く 5 が「185」になって 75 まで飛ぶ。
 * そこで Input type="number"（spinbutton の意味づけと矢印キーはそのまま）に、
 * 入力中は丸めず、範囲外の値だけ確定を保留して blur で丸める処理を足している。
 *
 * 読み上げの組み立て:
 * - 見出しは group の aria-labelledby で1回だけ持つ。つまみが可視ラベルを受け取り、
 *   直接入力欄は「〜（直接入力）」という別名にして、同じ名前が二重に出ないようにする。
 * - 補足文は id をひとつ作り、つまみと入力欄の両方から aria-describedby で参照する。
 * - 現在値の output は group の見出し行に置き、htmlFor でつまみに結びつける。
 */
export function QuoteRangeField({
    label,
    value,
    onValueChange,
    min,
    max,
    step,
    description,
    formatValue,
    minLabel,
    maxLabel,
    inputClassName,
    className,
}: QuoteRangeFieldProps) {
    const uid = React.useId();
    const sliderId = `${uid}-slider`;
    const numberId = `${uid}-number`;
    const labelId = `${uid}-label`;
    const descriptionId = description ? `${uid}-description` : undefined;

    // 入力中の文字列。null のあいだは確定値をそのまま表示する
    const [draft, setDraft] = React.useState<string | null>(null);
    const display = draft ?? String(value);

    const commit = (raw: string) => {
        const parsed = Number(raw);
        if (raw === "" || Number.isNaN(parsed)) return;
        onValueChange(clamp(Math.round(parsed / step) * step, min, max));
    };

    const handleNumberChange = (event: React.ChangeEvent<HTMLInputElement>) => {
        const raw = event.target.value;
        setDraft(raw);
        const parsed = Number(raw);
        // 範囲内になった時点だけ反映する。範囲外のあいだは打ち終わるのを待つ
        if (raw !== "" && !Number.isNaN(parsed) && parsed >= min && parsed <= max) {
            onValueChange(parsed);
        }
    };

    const handleNumberBlur = () => {
        if (draft !== null) commit(draft);
        setDraft(null);
    };

    const nudge = (delta: number) => {
        setDraft(null);
        onValueChange(clamp(value + delta, min, max));
    };

    return (
        <div
            role="group"
            aria-labelledby={labelId}
            className={cn("flex w-full flex-col gap-2", className)}
        >
            <div className="flex items-baseline justify-between gap-2">
                <Label id={labelId} htmlFor={sliderId} className="text-sm">
                    {label}
                </Label>
                {/* output は暗黙で aria-live="polite" のため、つまみを動かすたびに
                    読み上げが走ってしまう。ここは目で見るための表示に徹し、
                    値の読み上げはつまみ自身の aria-valuetext にまかせる */}
                <output
                    htmlFor={sliderId}
                    aria-live="off"
                    className="text-base font-semibold tabular-nums text-foreground"
                >
                    {formatValue(value)}
                </output>
            </div>

            <div className="flex min-w-0 flex-col gap-1">
                <Slider
                    id={sliderId}
                    min={min}
                    max={max}
                    step={step}
                    value={value}
                    onValueChange={(next) => {
                        setDraft(null);
                        onValueChange(next);
                    }}
                    formatValue={formatValue}
                    aria-describedby={descriptionId}
                />
                {(minLabel || maxLabel) && (
                    <div
                        aria-hidden="true"
                        className="flex justify-between text-[11px] tabular-nums text-muted-foreground"
                    >
                        <span>{minLabel}</span>
                        <span>{maxLabel}</span>
                    </div>
                )}
            </div>

            <div className="flex items-center gap-2">
                <Button
                    type="button"
                    variant="outline"
                    size="icon"
                    onClick={() => nudge(-step)}
                    disabled={value <= min}
                    aria-label={`${label}を${step.toLocaleString("ja-JP")}減らす`}
                >
                    <Icon icon={IconMinus} size="sm" decorative />
                </Button>
                <Input
                    id={numberId}
                    type="number"
                    inputMode="numeric"
                    min={min}
                    max={max}
                    step={step}
                    value={display}
                    onChange={handleNumberChange}
                    onBlur={handleNumberBlur}
                    aria-label={`${label}（直接入力）`}
                    aria-describedby={descriptionId}
                    className={cn("w-28 text-right tabular-nums", inputClassName)}
                />
                <Button
                    type="button"
                    variant="outline"
                    size="icon"
                    onClick={() => nudge(step)}
                    disabled={value >= max}
                    aria-label={`${label}を${step.toLocaleString("ja-JP")}増やす`}
                >
                    <Icon icon={IconPlus} size="sm" decorative />
                </Button>
            </div>

            {description && (
                <p id={descriptionId} className="text-xs text-muted-foreground">
                    {description}
                </p>
            )}
        </div>
    );
}
